 "content": "from collections import Counter, deque


def transform(grid):
    """Fill each four-connected enclosed background region with color 4."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while queue:
                x, y = queue.popleft()
                component.append((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    touches_edge = True
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w
                            and grid[nx][ny] == background
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        queue.append((nx, ny))
            if not touches_edge:
                for x, y in component:
                    out[x][y] = 4
    return out


